  var c = this.channels[ch];
  if (!c || !ins) return;
  copyOpParams(c.mod, ins.mod, ins.modWave || 0);
  copyOpParams(c.car, ins.car, ins.carWave || 0);
  c.feedback = ins.mod.feedback & 7;
